content.css:
.bf360-host {
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  color: #1F2430;
  background: #FFFFFF;
  position: relative;
  overflow: hidden;
  height: 100%;
  width: 100%;
  box-sizing: border-box;
  padding-bottom: 24px;
}
.bf360-host * {
  box-sizing: border-box;
}
.bf360-root {
  position: relative;
  height: 100%;
  width: 100%;
  overflow: auto;
}
.bf360-main {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}
.bf360-band {
  background: var(--bf360-header-bg, #1F2A44);
  color: var(--bf360-header-text, #fff);
  padding: 14px 24px 12px;
  position: relative;
  border-bottom: 3px solid var(--bf360-brand, #E8612A);
}
.bf360-band__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.bf360-band__title-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}
.bf360-band__title {
  margin: 0;
  font-size: 22px;
  font-weight: 600;
  color: var(--bf360-header-text, #fff);
  line-height: 1.1;
  letter-spacing: 0.01em;
}
.bf360-band__subtitle {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.75);
  margin-top: 2px;
  letter-spacing: 0.04em;
}
.bf360-band__right {
  display: flex;
  align-items: center;
  gap: 14px;
}
.bf360-band__period {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  padding: 4px 10px;
  border-radius: 4px;
  font-size: 11.5px;
  color: #fff;
  font-weight: 600;
  letter-spacing: 0.03em;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: inherit;
  line-height: 1.2;
}
.bf360-band__period--clickable {
  cursor: pointer;
}
.bf360-band__period--clickable:hover {
  background: rgba(255, 255, 255, 0.16);
  border-color: var(--bf360-brand, #E8612A);
}
.bf360-band__period:disabled {
  cursor: default;
  opacity: 0.85;
}
.bf360-band__period-prev {
  font-weight: 400;
  opacity: 0.7;
}
.bf360-band__period-caret {
  font-size: 9px;
  opacity: 0.8;
  margin-left: 2px;
}
.bf360-band__key {
  color: rgba(255, 255, 255, 0.7);
  font-size: 10.5px;
  font-style: italic;
  letter-spacing: 0.02em;
  margin-top: 6px;
}
.bf360-info-btn {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.4);
  background: transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 600;
  font-style: italic;
  color: #fff;
  cursor: pointer;
  padding: 0;
}
.bf360-info-btn:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: var(--bf360-brand, #E8612A);
}
.bf360-whatif {
  display: flex;
  align-items: center;
  gap: 10px;
  color: rgba(255, 255, 255, 0.85);
  font-size: 11px;
}
.bf360-whatif + .bf360-whatif {
  margin-left: 4px;
}
.bf360-whatif input[type=range] {
  width: 80px;
  accent-color: var(--bf360-brand, #E8612A);
}
.bf360-whatif__val {
  font-weight: 600;
  color: var(--bf360-brand, #E8612A);
  min-width: 28px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.bf360-shell {
  display: grid;
  grid-template-columns: 1fr 240px;
  gap: 0;
  flex: 1;
  min-height: 0;
}
.bf360-area {
  padding: 18px 20px 12px;
  display: flex;
  flex-direction: column;
  gap: 18px;
  min-width: 0;
  overflow: auto;
}
.bf360-hero {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
}
.bf360-tile {
  background: #FFFFFF;
  border: 1px solid #E3E6EC;
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  min-width: 0;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}
.bf360-tile--lead {
  border-top: 3px solid var(--bf360-brand, #E8612A);
}
.bf360-tile__banner {
  color: #fff;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 6px 12px;
  text-transform: uppercase;
  background: var(--bf360-banner-primary, #1F2A44);
}
.bf360-tile__banner--accent {
  background: var(--bf360-banner-accent, #E8612A);
}
.bf360-tile__banner--teal {
  background: #1e6d6e;
}
.bf360-tile__body {
  padding: 10px 12px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}
.bf360-tile__row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  justify-content: space-between;
}
.bf360-tile__value {
  font-size: 24px;
  font-weight: 600;
  color: #1F2430;
  line-height: 1.05;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bf360-tile__value--heading {
  font-size: 17px;
  font-weight: 600;
}
.bf360-tile__delta {
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.bf360-tile__delta--up {
  color: var(--bf360-on-track, #1e6d6e);
}
.bf360-tile__delta--down {
  color: var(--bf360-off-track, #C0392B);
}
.bf360-tile__delta--flat {
  color: #6B7280;
}
.bf360-tile__stats {
  font-size: 10.5px;
  color: #6B7280;
  line-height: 1.4;
  margin-top: 2px;
}
.bf360-tile__stats div {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bf360-tile__chart {
  margin-top: 6px;
  height: 48px;
}
.bf360-hchart {
  width: 100%;
  height: 48px;
  display: block;
}
.bf360-hchart__target {
  fill: none;
  stroke: rgba(0, 0, 0, 0.28);
  stroke-width: 1;
  stroke-dasharray: 3 2;
}
.bf360-hchart__target-lbl {
  font-size: 7px;
  fill: #6B7280;
}
.bf360-hchart__area {
  fill: var(--bf360-on-track, #1e6d6e);
  opacity: 0.12;
}
.bf360-hchart__line {
  fill: none;
  stroke: var(--bf360-on-track, #1e6d6e);
  stroke-width: 1.5;
}
.bf360-hchart__dot--ok {
  fill: var(--bf360-on-track, #1e6d6e);
}
.bf360-hchart__dot--risk {
  fill: var(--bf360-off-track, #C0392B);
}
.bf360-hchart__bar {
  fill: var(--bf360-bar-current, #1e6d6e);
}
.bf360-hchart__bar--last {
  fill: var(--bf360-brand, #E8612A);
}
.bf360-hchart__barval {
  font-size: 8px;
  fill: #1F2430;
  font-weight: 600;
}
.bf360-hchart__xlabel {
  font-size: 7px;
  fill: #6B7280;
}
.bf360-hchart--risk .bf360-hchart__line {
  stroke: var(--bf360-off-track, #C0392B);
}
.bf360-hchart--risk .bf360-hchart__area {
  fill: var(--bf360-off-track, #C0392B);
}
.bf360-hchart--warn .bf360-hchart__line {
  stroke: var(--bf360-at-risk, #D9A832);
}
.bf360-hchart--warn .bf360-hchart__area {
  fill: var(--bf360-at-risk, #D9A832);
}
.bf360-section {
  border: 1px solid #E3E6EC;
  border-radius: 6px;
  background: #FFFFFF;
  overflow: hidden;
}
.bf360-section__head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  background: #F5F6F8;
  border-bottom: 1px solid #E3E6EC;
  border-left: 3px solid var(--bf360-brand, #E8612A);
}
.bf360-section__title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #1F2430;
}
.bf360-section__subtitle {
  font-size: 11px;
  color: #6B7280;
  margin-left: auto;
  font-weight: 400;
  letter-spacing: 0;
}
.bf360-section__body {
  padding: 12px 14px 14px;
}
.bf360-section--financial .bf360-section__head {
  border-left-color: var(--bf360-brand, #E8612A);
}
.bf360-section--schedule .bf360-section__head {
  border-left-color: var(--bf360-banner-primary, #1F2A44);
}
.bf360-section--resources .bf360-section__head {
  border-left-color: #1e6d6e;
}
.bf360-section--risks .bf360-section__head {
  border-left-color: var(--bf360-off-track, #C0392B);
}
.bf360-subgrid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
}
.bf360-subpanel {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.bf360-subpanel__title {
  font-size: 11.5px;
  font-weight: 600;
  color: #1F2430;
  line-height: 1.3;
}
.bf360-subpanel__subtitle {
  font-size: 10.5px;
  color: #6B7280;
  line-height: 1.3;
  margin-top: -2px;
}
.bf360-pos {
  color: var(--bf360-on-track, #1e6d6e);
  font-weight: 600;
}
.bf360-neg {
  color: var(--bf360-off-track, #C0392B);
  font-weight: 600;
}
.bf360-bullets {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 4px;
}
.bf360-bullet {
  display: grid;
  grid-template-columns: 88px 1fr 64px;
  gap: 8px;
  align-items: center;
}
.bf360-bullet__label {
  font-size: 11px;
  color: #1F2430;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bf360-bullet__track {
  position: relative;
  height: 14px;
}
.bf360-bullet__bg {
  background: #F5F6F8;
  height: 12px;
  width: 100%;
  position: relative;
  overflow: visible;
  border-radius: 2px;
}
.bf360-bullet__fill {
  height: 100%;
  background: var(--bf360-on-track, #1e6d6e);
  border-radius: 2px;
}
.bf360-bullet__fill--ok {
  background: var(--bf360-on-track, #1e6d6e);
}
.bf360-bullet__fill--warn {
  background: var(--bf360-at-risk, #D9A832);
}
.bf360-bullet__fill--risk {
  background: var(--bf360-off-track, #C0392B);
}
.bf360-bullet__tick {
  position: absolute;
  top: -2px;
  bottom: -2px;
  width: 2px;
  background: #1a1a1a;
}
.bf360-bullet__val {
  font-size: 10.5px;
  color: #1F2430;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.bf360-ranked {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 4px;
}
.bf360-rank {
  display: grid;
  grid-template-columns: 84px 1fr 44px;
  gap: 8px;
  align-items: center;
}
.bf360-rank__label {
  font-size: 11px;
  color: #1F2430;
  line-height: 1.2;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.bf360-rank__bars {
  display: flex;
  flex-direction: column;
  gap: 2px;
  position: relative;
}
.bf360-rank__bar {
  height: 10px;
  position: relative;
  display: flex;
  align-items: center;
  border-radius: 2px;
}
.bf360-rank__bar span {
  position: absolute;
  right: 4px;
  top: -1px;
  font-size: 9.5px;
  color: #1F2430;
  font-variant-numeric: tabular-nums;
  line-height: 12px;
  font-weight: 600;
}
.bf360-rank__bar--cur {
  background: var(--bf360-bar-current, #1e6d6e);
}
.bf360-rank__bar--prv {
  background: var(--bf360-bar-previous, #d9dde3);
}
.bf360-rank__bar--cur span {
  color: #fff;
  text-shadow: 0 0 2px rgba(0, 0, 0, 0.4);
}
.bf360-rank__pill {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--bf360-bar-current, #2c8b8b);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12);
  position: relative;
}
.bf360-heat {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin-top: 4px;
}
.bf360-heat-cell {
  border-radius: 4px;
  padding: 10px 8px 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  border: 1px solid #E3E6EC;
  background: #F5F6F8;
}
.bf360-heat-cell__label {
  font-size: 10px;
  color: #6B7280;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 700;
}
.bf360-heat-cell__val {
  font-size: 20px;
  font-weight: 700;
  color: #1F2430;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.bf360-heat-cell__sub {
  font-size: 10px;
  color: #6B7280;
}
.bf360-heat-cell--ok {
  border-left: 3px solid var(--bf360-on-track, #1e6d6e);
}
.bf360-heat-cell--warn {
  border-left: 3px solid var(--bf360-at-risk, #D9A832);
}
.bf360-heat-cell--risk {
  border-left: 3px solid var(--bf360-off-track, #C0392B);
}
.bf360-cap {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 4px;
}
.bf360-cap-row__hdr {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #1F2430;
  margin-bottom: 3px;
}
.bf360-cap-row__hdr b {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}
.bf360-cap-row__track {
  position: relative;
  height: 12px;
  background: #F5F6F8;
  border-radius: 2px;
  overflow: visible;
}
.bf360-cap-row__cap {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  background: linear-gradient(90deg, #2c8b8b, #1e6d6e);
  border-radius: 2px;
}
.bf360-cap-row__dem {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  background: var(--bf360-brand, #E8612A);
  opacity: 0.85;
  border-radius: 2px;
  border-right: 2px solid #fff;
}
.bf360-cap-row__over {
  position: absolute;
  right: 0;
  top: -3px;
  font-size: 10px;
  font-weight: 700;
  color: var(--bf360-off-track, #C0392B);
  font-variant-numeric: tabular-nums;
}
.bf360-funnel {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 4px;
}
.bf360-funnel-row {
  display: grid;
  grid-template-columns: 90px 1fr 32px;
  gap: 8px;
  align-items: center;
}
.bf360-funnel-row__lbl {
  font-size: 11px;
  color: #1F2430;
}
.bf360-funnel-row__bg {
  background: #F5F6F8;
  border-radius: 2px;
  height: 12px;
  position: relative;
}
.bf360-funnel-row__fill {
  background: var(--bf360-banner-primary, #1F2A44);
  height: 100%;
  border-radius: 2px;
  opacity: 0.88;
}
.bf360-funnel-row__cnt {
  font-size: 11px;
  font-weight: 600;
  color: #1F2430;
  font-variant-numeric: tabular-nums;
  text-align: right;
}
.bf360-empty-note {
  font-size: 11px;
  color: #6B7280;
  font-style: italic;
  padding: 6px 2px;
}
.bf360-rail {
  background: #F5F6F8;
  border-left: 1px solid #E3E6EC;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: width 180ms ease;
}
.bf360-rail__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 12px 10px;
  border-bottom: 1px solid #E3E6EC;
  background: #FFFFFF;
}
.bf360-rail__head-lbl {
  font-size: 10.5px;
  color: #6B7280;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
}
.bf360-rail__toggle {
  cursor: pointer;
  border: 1px solid #E3E6EC;
  background: #FFFFFF;
  border-radius: 3px;
  width: 22px;
  height: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  color: #6B7280;
  padding: 0;
}
.bf360-rail__toggle:hover {
  color: var(--bf360-brand, #E8612A);
  border-color: var(--bf360-brand, #E8612A);
}
.bf360-rail__body {
  flex: 1;
  overflow: auto;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.bf360-rail--collapsed .bf360-rail__head-lbl,
.bf360-rail--collapsed .bf360-rail__body {
  display: none;
}
.bf360-rail--collapsed .bf360-rail__head {
  justify-content: center;
  padding: 8px 4px;
}
.bf360-insight {
  background: #FFFFFF;
  border: 1px solid #E3E6EC;
  border-left: 3px solid #1e6d6e;
  border-radius: 4px;
  padding: 7px 9px;
  font-size: 11px;
  line-height: 1.4;
}
.bf360-insight__tag {
  display: inline-block;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #6B7280;
  margin-bottom: 2px;
}
.bf360-insight--ok {
  border-left-color: var(--bf360-on-track, #1e6d6e);
}
.bf360-insight--warn {
  border-left-color: var(--bf360-at-risk, #D9A832);
}
.bf360-insight--risk {
  border-left-color: var(--bf360-off-track, #C0392B);
}
.bf360-insight--brand {
  border-left-color: var(--bf360-brand, #E8612A);
}
.bf360-insight strong {
  color: #1F2430;
}
.bf360-period-pop {
  position: absolute;
  background: #FFFFFF;
  border: 1px solid #E3E6EC;
  border-radius: 6px;
  box-shadow: 0 6px 24px rgba(15, 23, 42, 0.2);
  z-index: 110;
  min-width: 200px;
  max-width: 260px;
  font-size: 12px;
  color: #1F2430;
  overflow: hidden;
}
.bf360-period-pop__head {
  padding: 8px 12px 6px;
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 700;
  color: #6B7280;
  border-bottom: 1px solid #E3E6EC;
  background: #F5F6F8;
}
.bf360-period-pop__list {
  max-height: 320px;
  overflow: auto;
  display: flex;
  flex-direction: column;
  padding: 4px 0;
}
.bf360-period-pop__item {
  appearance: none;
  background: transparent;
  border: none;
  text-align: left;
  padding: 7px 14px;
  font-family: inherit;
  font-size: 12px;
  color: #1F2430;
  cursor: pointer;
  line-height: 1.2;
  border-left: 3px solid transparent;
}
.bf360-period-pop__item:hover {
  background: #F5F6F8;
}
.bf360-period-pop__item--reset {
  color: #6B7280;
  font-style: italic;
  border-bottom: 1px solid #E3E6EC;
  margin-bottom: 4px;
}
.bf360-period-pop__item--active {
  background: rgba(232, 97, 42, 0.08);
  border-left-color: var(--bf360-brand, #E8612A);
  color: #1F2430;
  font-weight: 600;
}
.bf360-period-pop__item--current {
  color: var(--bf360-on-track, #1e6d6e);
  font-weight: 600;
}
.bf360-period-pop__item--current::after {
  content: " • current";
  font-weight: 400;
  opacity: 0.6;
}
.bf360-info-pop {
  position: absolute;
  top: 56px;
  left: 26px;
  background: #FFFFFF;
  border: 1px solid #E3E6EC;
  border-radius: 6px;
  box-shadow: 0 6px 24px rgba(15, 23, 42, 0.2);
  padding: 14px 16px 12px;
  max-width: 380px;
  z-index: 100;
  font-size: 12px;
  line-height: 1.45;
  color: #1F2430;
}
.bf360-info-pop__close {
  position: absolute;
  top: 6px;
  right: 8px;
  background: transparent;
  border: none;
  font-size: 18px;
  color: #6B7280;
  cursor: pointer;
  line-height: 1;
  padding: 2px;
}
.bf360-info-pop__close:hover {
  color: #1F2430;
}
.bf360-info-pop__title {
  font-size: 13px;
  font-weight: 700;
  color: #1F2430;
  border-bottom: 2px solid var(--bf360-brand, #E8612A);
  padding-bottom: 4px;
  margin-bottom: 8px;
}
.bf360-info-pop__desc {
  margin: 0 0 8px;
}
.bf360-info-pop__sub {
  font-size: 11px;
  font-weight: 600;
  color: #6B7280;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 4px;
}
.bf360-info-pop__bullets {
  margin: 0;
  padding-left: 16px;
}
.bf360-info-pop__bullets li {
  margin-bottom: 3px;
}
.bfusion-landing {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 24px;
}
.bfusion-landing__logo {
  width: 80px;
  height: auto;
  border-radius: 12px;
}
.bfusion-landing__title {
  margin: 0 0 6px;
  font-size: 16px;
  color: #1F2430;
}
.bfusion-landing__description {
  margin: 0;
  font-size: 12px;
  color: #6B7280;
  line-height: 1.5;
}
.bfusion-landing__separator {
  height: 1px;
  background: #E3E6EC;
  margin: 10px 0;
}
.bfusion-landing__metadata {
  font-size: 11px;
  color: #6B7280;
}
.bfusion-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 24px;
}
.bfusion-empty__message {
  font-size: 13px;
  color: #6B7280;
  font-style: italic;
}
.bf360-landing-wrap {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.bfusion-license-badge-wrap {
  position: absolute;
  left: 0;
  bottom: 0;
  right: 0;
  height: 24px;
  pointer-events: none;
}
.bf360-host.bf360-medium .bf360-band {
  padding: 12px 16px 10px;
}
.bf360-host.bf360-medium .bf360-band__title {
  font-size: 18px;
}
.bf360-host.bf360-medium .bf360-shell {
  grid-template-columns: 1fr 200px;
}
.bf360-host.bf360-medium .bf360-area {
  padding: 14px 14px 10px;
  gap: 14px;
}
.bf360-host.bf360-medium .bf360-hero {
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}
.bf360-host.bf360-medium .bf360-tile__value {
  font-size: 20px;
}
.bf360-host.bf360-medium .bf360-tile__value--heading {
  font-size: 15px;
}
.bf360-host.bf360-medium .bf360-subgrid {
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.bf360-host.bf360-medium .bf360-subpanel:nth-child(3) {
  grid-column: 1 / -1;
}
.bf360-host.bf360-medium .bf360-bullet {
  grid-template-columns: 80px 1fr 56px;
}
.bf360-host.bf360-narrow .bf360-band {
  padding: 10px 12px 8px;
}
.bf360-host.bf360-narrow .bf360-band__title {
  font-size: 16px;
}
.bf360-host.bf360-narrow .bf360-band__top {
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
}
.bf360-host.bf360-narrow .bf360-band__right {
  flex-wrap: wrap;
  gap: 8px;
}
.bf360-host.bf360-narrow .bf360-shell {
  grid-template-columns: 1fr;
  position: relative;
}
.bf360-host.bf360-narrow .bf360-rail {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: 240px;
  z-index: 30;
  box-shadow: -4px 0 12px rgba(15, 23, 42, 0.1);
}
.bf360-host.bf360-narrow .bf360-rail--collapsed {
  width: 28px;
  box-shadow: none;
}
.bf360-host.bf360-narrow .bf360-area {
  padding: 12px 12px 10px;
  gap: 12px;
  padding-right: 36px;
}
.bf360-host.bf360-narrow .bf360-hero {
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}
.bf360-host.bf360-narrow .bf360-tile__value {
  font-size: 18px;
}
.bf360-host.bf360-narrow .bf360-tile__value--heading {
  font-size: 13.5px;
}
.bf360-host.bf360-narrow .bf360-tile__chart {
  height: 40px;
}
.bf360-host.bf360-narrow .bf360-subgrid {
  grid-template-columns: 1fr;
  gap: 10px;
}
.bf360-host.bf360-narrow .bf360-heat {
  grid-template-columns: repeat(2, 1fr);
}
